     1→// Performance measurement utilities
     2→// Macros and utilities for profiling and benchmarking the runtime
     3→
     4→use std::time::{Instant, Duration};
     5→
     6→/// Performance counter for measuring execution time
     7→#[derive(Clone, Debug)]
     8→pub struct PerfCounter {
     9→    pub name: String,
    10→    pub count: u64,
    11→    pub total_time: Duration,
    12→    pub min_time: Duration,
    13→    pub max_time: Duration,
    14→}
    15→
    16→impl PerfCounter {
    17→    pub fn new(name: &str) -> Self {
    18→        PerfCounter {
    19→            name: name.to_string(),
    20→            count: 0,
    21→            total_time: Duration::ZERO,
    22→            min_time: Duration::MAX,
    23→            max_time: Duration::ZERO,
    24→        }
    25→    }
    26→
    27→    pub fn record(&mut self, duration: Duration) {
    28→        self.count += 1;
    29→        self.total_time += duration;
    30→        if duration < self.min_time {
    31→            self.min_time = duration;
    32→        }
    33→        if duration > self.max_time {
    34→            self.max_time = duration;
    35→        }
    36→    }
    37→
    38→    pub fn avg_time_us(&self) -> f64 {
    39→        if self.count == 0 {
    40→            0.0
    41→        } else {
    42→            self.total_time.as_micros() as f64 / self.count as f64
    43→        }
    44→    }
    45→
    46→    pub fn avg_time_ns(&self) -> f64 {
    47→        if self.count == 0 {
    48→            0.0
    49→        } else {
    50→            self.total_time.as_nanos() as f64 / self.count as f64
    51→        }
    52→    }
    53→
    54→    pub fn total_time_ms(&self) -> f64 {
    55→        self.total_time.as_secs_f64() * 1000.0
    56→    }
    57→
    58→    pub fn throughput(&self) -> f64 {
    59→        if self.total_time.as_secs_f64() == 0.0 {
    60→            0.0
    61→        } else {
    62→            self.count as f64 / self.total_time.as_secs_f64()
    63→        }
    64→    }
    65→}
    66→
    67→impl std::fmt::Display for PerfCounter {
    68→    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
    69→        write!(
    70→            f,
    71→            "{}: {} calls, avg {:.2}μs ({:.0}ns), min {:.2}μs, max {:.2}μs, total {:.2}ms, throughput {:.0} ops/sec",
    72→            self.name,
    73→            self.count,
    74→            self.avg_time_us(),
    75→            self.avg_time_ns(),
    76→            self.min_time.as_micros() as f64,
    77→            self.max_time.as_micros() as f64,
    78→            self.total_time_ms(),
    79→            self.throughput()
    80→        )
    81→    }
    82→}
    83→
    84→/// Macro for timing a block of code
    85→#[macro_export]
    86→macro_rules! measure {
    87→    ($counter:expr, $block:block) => {{
    88→        let start = std::time::Instant::now();
    89→        let result = $block;
    90→        let elapsed = start.elapsed();
    91→        $counter.record(elapsed);
    92→        result
    93→    }};
    94→}
    95→
    96→/// Macro for quick timing
    97→#[macro_export]
    98→macro_rules! time_it {
    99→    ($name:expr, $block:block) => {{
   100→        let start = std::time::Instant::now();
   101→        let result = $block;
   102→        let elapsed = start.elapsed();
   103→        println!("{}: {:.2}μs ({:.0}ns)", $name, elapsed.as_micros() as f64, elapsed.as_nanos() as f64);
   104→        result
   105→    }};
   106→}
   107→
   108→#[cfg(test)]
   109→mod tests {
   110→    use super::*;
   111→
   112→    #[test]
   113→    fn test_perf_counter_creation() {
   114→        let counter = PerfCounter::new("test");
   115→        assert_eq!(counter.count, 0);
   116→        assert_eq!(counter.name, "test");
   117→    }
   118→
   119→    #[test]
   120→    fn test_perf_counter_recording() {
   121→        let mut counter = PerfCounter::new("test");
   122→        counter.record(Duration::from_micros(100));
   123→        counter.record(Duration::from_micros(200));
   124→
   125→        assert_eq!(counter.count, 2);
   126→        assert_eq!(counter.min_time, Duration::from_micros(100));
   127→        assert_eq!(counter.max_time, Duration::from_micros(200));
   128→        assert!((counter.avg_time_us() - 150.0).abs() < 0.1);
   129→    }
   130→
   131→    #[test]
   132→    fn test_perf_counter_throughput() {
   133→        let mut counter = PerfCounter::new("test");
   134→        for _ in 0..1000 {
   135→            counter.record(Duration::from_micros(1));
   136→        }
   137→        // 1000 ops in 1000μs = 1 million ops/sec
   138→        assert!((counter.throughput() - 1_000_000.0).abs() < 100_000.0);
   139→    }
   140→}
