     1→// Function Type System
     2→// Represents different kinds of functions in FreeLang
     3→
     4→use crate::core::Value;
     5→use std::collections::HashMap;
     6→use std::rc::Rc;
     7→use std::cell::RefCell;
     8→
     9→/// Function signature type
    10→pub type NativeFunction = fn(Vec<Value>) -> Result<Value, String>;
    11→
    12→/// Represents a user-defined function
    13→#[derive(Clone)]
    14→pub struct UserFunction {
    15→    pub name: String,
    16→    pub params: Vec<String>,
    17→    pub body: Vec<Value>, // Instructions/expressions
    18→    pub closure: Rc<RefCell<HashMap<String, Value>>>,
    19→}
    20→
    21→impl UserFunction {
    22→    /// Create new user-defined function
    23→    pub fn new(
    24→        name: String,
    25→        params: Vec<String>,
    26→        body: Vec<Value>,
    27→    ) -> Self {
    28→        UserFunction {
    29→            name,
    30→            params,
    31→            body,
    32→            closure: Rc::new(RefCell::new(HashMap::new())),
    33→        }
    34→    }
    35→
    36→    /// Get parameter count
    37→    pub fn param_count(&self) -> usize {
    38→        self.params.len()
    39→    }
    40→
    41→    /// Get function name
    42→    pub fn get_name(&self) -> &str {
    43→        &self.name
    44→    }
    45→
    46→    /// Get parameters
    47→    pub fn get_params(&self) -> &[String] {
    48→        &self.params
    49→    }
    50→
    51→    /// Set closure variable
    52→    pub fn set_closure_var(&self, name: String, value: Value) {
    53→        self.closure.borrow_mut().insert(name, value);
    54→    }
    55→
    56→    /// Get closure variable
    57→    pub fn get_closure_var(&self, name: &str) -> Option<Value> {
    58→        self.closure.borrow().get(name).cloned()
    59→    }
    60→}
    61→
    62→impl std::fmt::Debug for UserFunction {
    63→    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
    64→        f.debug_struct("UserFunction")
    65→            .field("name", &self.name)
    66→            .field("params", &self.params)
    67→            .field("param_count", &self.param_count())
    68→            .finish()
    69→    }
    70→}
    71→
    72→impl std::fmt::Display for UserFunction {
    73→    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
    74→        write!(f, "[Function: {}({})]", self.name, self.params.join(", "))
    75→    }
    76→}
    77→
    78→/// Function kind enumeration
    79→#[derive(Clone)]
    80→pub enum FunctionKind {
    81→    /// Native stdlib function
    82→    Native(NativeFunction),
    83→    /// User-defined function
    84→    User(UserFunction),
    85→    /// Closure (captures variables)
    86→    Closure {
    87→        func: UserFunction,
    88→        captured: Rc<RefCell<HashMap<String, Value>>>,
    89→    },
    90→}
    91→
    92→impl std::fmt::Debug for FunctionKind {
    93→    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
    94→        match self {
    95→            FunctionKind::Native(_) => f.write_str("Native"),
    96→            FunctionKind::User(uf) => write!(f, "User({})", uf.name),
    97→            FunctionKind::Closure { func, .. } => write!(f, "Closure({})", func.name),
    98→        }
    99→    }
   100→}
   101→
   102→impl FunctionKind {
   103→    /// Call the function
   104→    pub fn call(&self, args: Vec<Value>) -> Result<Value, String> {
   105→        match self {
   106→            FunctionKind::Native(func) => func(args),
   107→            FunctionKind::User(_) => Err("User-defined functions require a runtime context".to_string()),
   108→            FunctionKind::Closure { .. } => Err("Closures require a runtime context".to_string()),
   109→        }
   110→    }
   111→
   112→    /// Check if this is a native function
   113→    pub fn is_native(&self) -> bool {
   114→        matches!(self, FunctionKind::Native(_))
   115→    }
   116→
   117→    /// Check if this is a user-defined function
   118→    pub fn is_user(&self) -> bool {
   119→        matches!(self, FunctionKind::User(_))
   120→    }
   121→
   122→    /// Check if this is a closure
   123→    pub fn is_closure(&self) -> bool {
   124→        matches!(self, FunctionKind::Closure { .. })
   125→    }
   126→
   127→    /// Get function name if available
   128→    pub fn name(&self) -> Option<&str> {
   129→        match self {
   130→            FunctionKind::User(uf) => Some(&uf.name),
   131→            FunctionKind::Closure { func, .. } => Some(&func.name),
   132→            FunctionKind::Native(_) => None,
   133→        }
   134→    }
   135→
   136→    /// Get parameter count if available
   137→    pub fn param_count(&self) -> Option<usize> {
   138→        match self {
   139→            FunctionKind::User(uf) => Some(uf.param_count()),
   140→            FunctionKind::Closure { func, .. } => Some(func.param_count()),
   141→            FunctionKind::Native(_) => None,
   142→        }
   143→    }
   144→}
   145→
   146→#[cfg(test)]
   147→mod tests {
   148→    use super::*;
   149→
   150→    #[test]
   151→    fn test_user_function_creation() {
   152→        let func = UserFunction::new(
   153→            "add".to_string(),
   154→            vec!["x".to_string(), "y".to_string()],
   155→            vec![],
   156→        );
   157→        assert_eq!(func.get_name(), "add");
   158→        assert_eq!(func.param_count(), 2);
   159→    }
   160→
   161→    #[test]
   162→    fn test_closure_variables() {
   163→        let func = UserFunction::new(
   164→            "multiply".to_string(),
   165→            vec!["x".to_string()],
   166→            vec![],
   167→        );
   168→        func.set_closure_var("factor".to_string(), Value::Number(2.0));
   169→        let var = func.get_closure_var("factor");
   170→        assert!(var.is_some());
   171→        assert_eq!(var.unwrap().to_number(), 2.0);
   172→    }
   173→
   174→    #[test]
   175→    fn test_native_function() {
   176→        fn add(args: Vec<Value>) -> Result<Value, String> {
   177→            if args.len() != 2 {
   178→                return Err("add requires 2 arguments".to_string());
   179→            }
   180→            Ok(Value::Number(args[0].to_number() + args[1].to_number()))
   181→        }
   182→
   183→        let func_kind = FunctionKind::Native(add);
   184→        assert!(func_kind.is_native());
   185→        assert!(!func_kind.is_user());
   186→
   187→        let result = func_kind.call(vec![Value::Number(2.0), Value::Number(3.0)]);
   188→        assert!(result.is_ok());
   189→        assert_eq!(result.unwrap().to_number(), 5.0);
   190→    }
   191→
   192→    #[test]
   193→    fn test_function_kind_debug() {
   194→        let user_func = UserFunction::new(
   195→            "test".to_string(),
   196→            vec!["x".to_string()],
   197→            vec![],
   198→        );
   199→        let kind = FunctionKind::User(user_func);
   200→        assert_eq!(format!("{:?}", kind), "User(test)");
   201→    }
   202→
   203→    #[test]
   204→    fn test_function_kind_name() {
   205→        let user_func = UserFunction::new(
   206→            "multiply".to_string(),
   207→            vec!["a".to_string(), "b".to_string()],
   208→            vec![],
   209→        );
   210→        let kind = FunctionKind::User(user_func);
   211→        assert_eq!(kind.name(), Some("multiply"));
   212→        assert_eq!(kind.param_count(), Some(2));
   213→    }
   214→}
