     1→// Runtime Virtual Machine
     2→// Main execution engine
     3→
     4→use crate::core::{Value, FunctionKind, UserFunction};
     5→use crate::memory::{MemoryAllocator, GarbageCollector, ReferenceCounter, MemoryStats};
     6→use crate::runtime::context::ExecutionContext;
     7→use crate::runtime::executor::Executor;
     8→use crate::runtime::callstack::CallStack;
     9→use crate::stdlib::FunctionRegistry;
    10→use std::time::Instant;
    11→
    12→/// Runtime engine statistics
    13→#[derive(Clone, Debug)]
    14→pub struct RuntimeStats {
    15→    pub uptime_ms: u128,
    16→    pub memory: MemoryStats,
    17→    pub memory_usage: usize,
    18→    pub call_depth: usize,
    19→    pub call_count: u64,
    20→}
    21→
    22→/// FreeLang runtime engine
    23→pub struct RuntimeEngine {
    24→    memory: MemoryAllocator,
    25→    gc: GarbageCollector,
    26→    refcount: ReferenceCounter,
    27→    context: ExecutionContext,
    28→    executor: Executor,
    29→    function_registry: FunctionRegistry,
    30→    call_stack: CallStack,
    31→    started_at: Instant,
    32→    execution_count: u64,
    33→}
    34→
    35→impl RuntimeEngine {
    36→    /// Create new runtime
    37→    pub fn new() -> Self {
    38→        RuntimeEngine {
    39→            memory: MemoryAllocator::new(),
    40→            gc: GarbageCollector::new(),
    41→            refcount: ReferenceCounter::new(),
    42→            context: ExecutionContext::new(),
    43→            executor: Executor::new(),
    44→            function_registry: FunctionRegistry::new(),
    45→            call_stack: CallStack::new(),
    46→            started_at: Instant::now(),
    47→            execution_count: 0,
    48→        }
    49→    }
    50→
    51→    /// Execute a value
    52→    pub fn execute(&mut self, value: Value) -> Result<Value, String> {
    53→        self.execution_count += 1;
    54→
    55→        // Check if GC should run
    56→        if self.memory.should_gc() {
    57→            self.run_gc();
    58→        }
    59→
    60→        Ok(value)
    61→    }
    62→
    63→    /// Execute binary operation
    64→    pub fn execute_binop(&mut self, op: &str, left: Value, right: Value) -> Result<Value, String> {
    65→        self.executor.binary_op(op, left, right)
    66→    }
    67→
    68→    /// Execute unary operation
    69→    pub fn execute_unop(&mut self, op: &str, operand: Value) -> Result<Value, String> {
    70→        self.executor.unary_op(op, operand)
    71→    }
    72→
    73→    /// Call a function
    74→    pub fn call_function(&mut self, func: Value, args: Vec<Value>) -> Result<Value, String> {
    75→        self.executor.call_function(func, args)
    76→    }
    77→
    78→    /// Call a stdlib function by name
    79→    pub fn call_stdlib(&self, name: &str, args: Vec<Value>) -> Result<Value, String> {
    80→        self.function_registry.call(name, args)
    81→    }
    82→
    83→    /// Check if function exists
    84→    pub fn function_exists(&self, name: &str) -> bool {
    85→        self.function_registry.exists(name)
    86→    }
    87→
    88→    /// List all available functions
    89→    pub fn list_functions(&self) -> Vec<&str> {
    90→        self.function_registry.list_functions()
    91→    }
    92→
    93→    /// Get function count
    94→    pub fn function_count(&self) -> usize {
    95→        self.function_registry.function_count()
    96→    }
    97→
    98→    /// Run garbage collection
    99→    fn run_gc(&mut self) {
   100→        // Mark phase
   101→        self.gc.mark(&[]);
   102→
   103→        // Sweep phase
   104→        self.gc.sweep();
   105→    }
   106→
   107→    /// Get memory statistics
   108→    pub fn memory_stats(&self) -> usize {
   109→        self.memory.memory_usage()
   110→    }
   111→
   112→    /// Get runtime statistics
   113→    pub fn stats(&self) -> RuntimeStats {
   114→        RuntimeStats {
   115→            uptime_ms: self.started_at.elapsed().as_millis(),
   116→            memory: MemoryStats {
   117→                allocated: 0,
   118→                freed: 0,
   119→                active: self.memory.object_count(),
   120→                gc_runs: 0,
   121→                gc_collected: 0,
   122→            },
   123→            memory_usage: self.memory.memory_usage(),
   124→            call_depth: self.call_stack.depth(),
   125→            call_count: self.call_stack.call_count(),
   126→        }
   127→    }
   128→
   129→    /// Call a user-defined function
   130→    pub fn call_user_function(
   131→        &mut self,
   132→        func: &UserFunction,
   133→        args: Vec<Value>,
   134→    ) -> Result<Value, String> {
   135→        // Push function frame
   136→        self.call_stack.push(func.get_name().to_string())?;
   137→
   138→        // Bind arguments to parameters
   139→        let params = func.get_params();
   140→        if args.len() != params.len() {
   141→            self.call_stack.pop();
   142→            return Err(format!(
   143→                "Function {} expects {} arguments, got {}",
   144→                func.get_name(),
   145→                params.len(),
   146→                args.len()
   147→            ));
   148→        }
   149→
   150→        for (param, arg) in params.iter().zip(args.iter()) {
   151→            self.call_stack.set_local(param.clone(), arg.clone())?;
   152→        }
   153→
   154→        // Execute function body
   155→        let mut result = Value::Null;
   156→        for instruction in func.get_params() {
   157→            // TODO: Execute instructions from function body
   158→            result = Value::Null;
   159→        }
   160→
   161→        // Pop frame
   162→        self.call_stack.pop();
   163→
   164→        Ok(result)
   165→    }
   166→
   167→    /// Call a function (stdlib or user-defined)
   168→    pub fn call_function(
   169→        &mut self,
   170→        name: &str,
   171→        args: Vec<Value>,
   172→    ) -> Result<Value, String> {
   173→        // Try stdlib first
   174→        if self.function_registry.exists(name) {
   175→            return self.call_stdlib(name, args);
   176→        }
   177→
   178→        // For user functions, we would look them up in a function table
   179→        // This is a placeholder for future implementation
   180→        Err(format!("Function '{}' not found", name))
   181→    }
   182→
   183→    /// Get call stack depth
   184→    pub fn call_depth(&self) -> usize {
   185→        self.call_stack.depth()
   186→    }
   187→
   188→    /// Get call stack trace
   189→    pub fn get_call_trace(&self) -> String {
   190→        self.call_stack.get_trace()
   191→    }
   192→
   193→    /// Get execution count
   194→    pub fn execution_count(&self) -> u64 {
   195→        self.execution_count
   196→    }
   197→
   198→    /// Get variable count
   199→    pub fn variable_count(&self) -> u64 {
   200→        self.context.variable_count()
   201→    }
   202→
   203→    /// Reset runtime
   204→    pub fn reset(&mut self) {
   205→        self.context.clear();
   206→        self.memory.reset();
   207→        self.gc.reset();
   208→        self.refcount.clear();
   209→        self.executor.reset_stats();
   210→        self.execution_count = 0;
   211→        self.started_at = Instant::now();
   212→    }
   213→}
   214→
   215→impl Default for RuntimeEngine {
   216→    fn default() -> Self {
   217→        Self::new()
   218→    }
   219→}
   220→
   221→#[cfg(test)]
   222→mod tests {
   223→    use super::*;
   224→
   225→    #[test]
   226→    fn test_runtime_creation() {
   227→        let engine = RuntimeEngine::new();
   228→        assert_eq!(engine.memory_stats(), 0);
   229→        assert_eq!(engine.execution_count(), 0);
   230→    }
   231→
   232→    #[test]
   233→    fn test_execute() {
   234→        let mut engine = RuntimeEngine::new();
   235→        let result = engine.execute(Value::Number(42.0));
   236→        assert!(result.is_ok());
   237→        assert_eq!(engine.execution_count(), 1);
   238→    }
   239→
   240→    #[test]
   241→    fn test_execute_binop() {
   242→        let mut engine = RuntimeEngine::new();
   243→        let result = engine.execute_binop("+", Value::Number(5.0), Value::Number(3.0));
   244→        assert!(result.is_ok());
   245→        assert_eq!(result.unwrap().to_number(), 8.0);
   246→    }
   247→
   248→    #[test]
   249→    fn test_execute_unop() {
   250→        let mut engine = RuntimeEngine::new();
   251→        let result = engine.execute_unop("-", Value::Number(5.0));
   252→        assert!(result.is_ok());
   253→        assert_eq!(result.unwrap().to_number(), -5.0);
   254→    }
   255→
   256→    #[test]
   257→    fn test_variable_tracking() {
   258→        let mut engine = RuntimeEngine::new();
   259→        engine.context.set_global("x".to_string(), Value::Number(42.0));
   260→        engine.context.set_local("y".to_string(), Value::Number(3.14));
   261→
   262→        assert_eq!(engine.variable_count(), 2);
   263→    }
   264→
   265→    #[test]
   266→    fn test_stats() {
   267→        let mut engine = RuntimeEngine::new();
