     5→
     6→/// Execution statistics
     7→#[derive(Clone, Debug)]
     8→pub struct ExecutionStats {
     9→    pub operations: u64,
    10→    pub function_calls: u64,
    11→    pub errors: u64,
    12→}
    13→
    14→/// Executor for FreeLang instructions
    15→pub struct Executor {
    16→    stats: ExecutionStats,
    17→}
    18→
    19→impl Executor {
    20→    /// Create new executor
    21→    pub fn new() -> Self {
    22→        Executor {
    23→            stats: ExecutionStats {
    24→                operations: 0,
    25→                function_calls: 0,
    26→                errors: 0,
    27→            },
    28→        }
    29→    }
    30→
    31→    /// Execute a function call
    32→    pub fn call_function(&mut self, func: Value, args: Vec<Value>) -> Result<Value, String> {
    33→        self.stats.function_calls += 1;
    34→        match func {
    35→            Value::Function(_) => {
    36→                // TODO: Implement function call
    37→                Ok(Value::Null)
    38→            }
    39→            _ => {
    40→                self.stats.errors += 1;
    41→                Err(format!("Cannot call non-function: {}", func.type_of()))
    42→            }
    43→        }
    44→    }
    45→
    46→    /// Execute binary operation
    47→    pub fn binary_op(&mut self, op: &str, left: Value, right: Value) -> Result<Value, String> {
    48→        self.stats.operations += 1;
    49→        match op {
    50→            "+" => {
    51→                let l = left.to_number();
    52→                let r = right.to_number();
    53→                Ok(Value::Number(l + r))
    54→            }
    55→            "-" => {
    56→                let l = left.to_number();
    57→                let r = right.to_number();
    58→                Ok(Value::Number(l - r))
    59→            }
    60→            "*" => {
    61→                let l = left.to_number();
    62→                let r = right.to_number();
    63→                Ok(Value::Number(l * r))
    64→            }
    65→            "/" => {
    66→                let l = left.to_number();
    67→                let r = right.to_number();
    68→                if r == 0.0 {
    69→                    self.stats.errors += 1;
    70→                    Err("Division by zero".to_string())
    71→                } else {
    72→                    Ok(Value::Number(l / r))
    73→                }
    74→            }
    75→            "%" => {
    76→                let l = left.to_number();
    77→                let r = right.to_number();
    78→                if r == 0.0 {
    79→                    self.stats.errors += 1;
    80→                    Err("Modulo by zero".to_string())
    81→                } else {
    82→                    Ok(Value::Number(l % r))
    83→                }
    84→            }
    85→            "==" => Ok(Value::Bool(left.equals(&right))),
    86→            "!=" => Ok(Value::Bool(!left.equals(&right))),
    87→            "<" => Ok(Value::Bool(left.to_number() < right.to_number())),
    88→            ">" => Ok(Value::Bool(left.to_number() > right.to_number())),
    89→            "<=" => Ok(Value::Bool(left.to_number() <= right.to_number())),
    90→            ">=" => Ok(Value::Bool(left.to_number() >= right.to_number())),
    91→            "&&" => Ok(Value::Bool(left.is_truthy() && right.is_truthy())),
    92→            "||" => Ok(Value::Bool(left.is_truthy() || right.is_truthy())),
    93→            _ => {
    94→                self.stats.errors += 1;
    95→                Err(format!("Unknown operator: {}", op))
    96→            }
    97→        }
    98→    }
    99→
   100→    /// Execute unary operation
   101→    pub fn unary_op(&mut self, op: &str, operand: Value) -> Result<Value, String> {
   102→        self.stats.operations += 1;
   103→        match op {
   104→            "-" => Ok(Value::Number(-operand.to_number())),
   105→            "!" => Ok(Value::Bool(!operand.is_truthy())),
   106→            "+" => Ok(Value::Number(operand.to_number())),
   107→            _ => {
   108→                self.stats.errors += 1;
   109→                Err(format!("Unknown unary operator: {}", op))
   110→            }
   111→        }
   112→    }
   113→
   114→    /// Get execution statistics
   115→    pub fn stats(&self) -> ExecutionStats {
   116→        self.stats.clone()
   117→    }
   118→
   119→    /// Reset statistics
   120→    pub fn reset_stats(&mut self) {
   121→        self.stats = ExecutionStats {
   122→            operations: 0,
   123→            function_calls: 0,
   124→            errors: 0,
   125→        };
   126→    }
   127→}
   128→
