    28→/// 각 함수 호출 지점에서 최근 호출 기록
    29→pub struct InlineCache {
    30→    // 호출 지점별 캐시 (key: callsite_id)
    31→    caches: HashMap<usize, InlineCacheEntry>,
    32→    // 전체 통계
    33→    total_hits: u64,
    34→    total_misses: u64,
    35→    total_polymorphic: u64,
    36→}
    37→
    38→impl InlineCache {
    39→    pub fn new() -> Self {
    40→        InlineCache {
    41→            caches: HashMap::new(),
    42→            total_hits: 0,
    43→            total_misses: 0,
    44→            total_polymorphic: 0,
    45→        }
    46→    }
    47→
    48→    /// Inline cache 조회 및 업데이트
    49→    pub fn lookup_and_update(&mut self, callsite_id: usize, function_name: &str) -> bool {
    50→        match self.caches.get_mut(&callsite_id) {
    51→            Some(entry) => {
    52→                if entry.function_name == function_name {
    53→                    // Cache hit - 같은 함수
    54→                    entry.call_count += 1;
    55→                    self.total_hits += 1;
    56→                    true
    57→                } else {
    58→                    // Cache miss - 다른 함수 호출
    59→                    entry.is_monomorphic = false;
    60→                    self.total_polymorphic += 1;
    61→                    self.total_misses += 1;
    62→                    false
    63→                }
    64→            }
    65→            None => {
    66→                // 첫 호출 - 캐시 생성
    67→                self.caches.insert(
    68→                    callsite_id,
    69→                    InlineCacheEntry {
    70→                        function_name: function_name.to_string(),
    71→                        call_count: 1,
    72→                        is_monomorphic: true,
    73→                    },
    74→                );
    75→                self.total_hits += 1;
    76→                true
    77→            }
    78→        }
    79→    }
    80→
    81→    /// Inline cache 통계
    82→    pub fn stats(&self) -> InlineCacheStats {
    83→        let total = self.total_hits + self.total_misses;
    84→        let hit_rate = if total == 0 {
    85→            0.0
    86→        } else {
    87→            (self.total_hits as f64 / total as f64) * 100.0
    88→        };
    89→
    90→        InlineCacheStats {
    91→            callsites: self.caches.len(),
    92→            monomorphic_sites: self
    93→                .caches
    94→                .values()
    95→                .filter(|e| e.is_monomorphic)
    96→                .count(),
    97→            polymorphic_sites: self
    98→                .caches
    99→                .values()
