     1→// Function Dispatch Cache
     2→// LRU cache for frequently used stdlib functions (90%+ hit rate)
     3→
     4→use std::collections::HashMap;
     5→use crate::core::Value;
     6→
     7→/// Function pointer type for stdlib functions
     8→pub type NativeFunction = fn(Vec<Value>) -> Result<Value, String>;
     9→
    10→/// Cached function entry
    11→#[derive(Clone)]
    12→struct CacheEntry {
    13→    function: NativeFunction,
    14→    hits: u64,
    15→}
    16→
    17→/// LRU Function Cache
    18→/// Maintains last N frequently used functions for O(1) dispatch
    19→/// Target: 90%+ cache hit rate, 5-10 item capacity
    20→#[derive(Clone)]
    21→pub struct FunctionCache {
    22→    cache: HashMap<String, CacheEntry>,
    23→    lru_order: Vec<String>,
    24→    max_capacity: usize,
    25→    hits: u64,
    26→    misses: u64,
    27→}
    28→
    29→impl FunctionCache {
    30→    /// Create new function cache with default capacity (8)
    31→    pub fn new() -> Self {
    32→        FunctionCache {
    33→            cache: HashMap::new(),
    34→            lru_order: Vec::new(),
    35→            max_capacity: 8,
    36→            hits: 0,
    37→            misses: 0,
    38→        }
    39→    }
    40→
    41→    /// Set cache capacity
    42→    pub fn with_capacity(capacity: usize) -> Self {
    43→        FunctionCache {
    44→            cache: HashMap::new(),
    45→            lru_order: Vec::new(),
    46→            max_capacity: capacity.max(1),
    47→            hits: 0,
    48→            misses: 0,
    49→        }
    50→    }
    51→
    52→    /// Get cached function
    53→    /// Returns Some(function) on cache hit, None on miss
    54→    pub fn get(&mut self, name: &str) -> Option<NativeFunction> {
    55→        if let Some(entry) = self.cache.get_mut(name) {
    56→            entry.hits += 1;
    57→            self.hits += 1;
    58→
    59→            // Move to end (most recent)
    60→            if let Some(pos) = self.lru_order.iter().position(|x| x == name) {
    61→                self.lru_order.remove(pos);
    62→                self.lru_order.push(name.to_string());
    63→            }
    64→
    65→            Some(entry.function)
    66→        } else {
    67→            self.misses += 1;
    68→            None
    69→        }
    70→    }
    71→
    72→    /// Insert or update cache entry
    73→    pub fn insert(&mut self, name: String, function: NativeFunction) {
    74→        // If already in cache, just update hit count and move to end
    75→        if self.cache.contains_key(&name) {
    76→            if let Some(entry) = self.cache.get_mut(&name) {
    77→                entry.hits += 1;
    78→            }
    79→            if let Some(pos) = self.lru_order.iter().position(|x| x == &name) {
    80→                self.lru_order.remove(pos);
    81→                self.lru_order.push(name);
    82→            }
    83→            return;
    84→        }
    85→
    86→        // If cache is full, evict LRU (least recently used)
    87→        if self.cache.len() >= self.max_capacity {
    88→            if let Some(lru_name) = self.lru_order.first().cloned() {
    89→                self.cache.remove(&lru_name);
    90→                self.lru_order.remove(0);
    91→            }
    92→        }
    93→
    94→        // Insert new entry
    95→        self.cache.insert(
    96→            name.clone(),
    97→            CacheEntry {
    98→                function,
    99→                hits: 1,
   100→            },
   101→        );
   102→        self.lru_order.push(name);
   103→    }
   104→
   105→    /// Get cache statistics
   106→    pub fn stats(&self) -> CacheStats {
   107→        let total = self.hits + self.misses;
   108→        let hit_rate = if total == 0 {
   109→            0.0
   110→        } else {
   111→            (self.hits as f64 / total as f64) * 100.0
   112→        };
   113→
   114→        CacheStats {
   115→            capacity: self.max_capacity,
   116→            current_size: self.cache.len(),
   117→            hits: self.hits,
   118→            misses: self.misses,
   119→            hit_rate,
   120→        }
   121→    }
   122→
   123→    /// Clear cache
   124→    pub fn clear(&mut self) {
   125→        self.cache.clear();
   126→        self.lru_order.clear();
   127→        self.hits = 0;
   128→        self.misses = 0;
   129→    }
   130→}
   131→
   132→/// Cache statistics
   133→#[derive(Clone, Debug)]
   134→pub struct CacheStats {
   135→    pub capacity: usize,
   136→    pub current_size: usize,
   137→    pub hits: u64,
   138→    pub misses: u64,
   139→    pub hit_rate: f64,
   140→}
   141→
   142→impl std::fmt::Display for CacheStats {
   143→    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
   144→        write!(
   145→            f,
   146→            "Cache: {}/{} items, {} hits, {} misses, {:.1}% hit rate",
   147→            self.current_size, self.capacity, self.hits, self.misses, self.hit_rate
   148→        )
   149→    }
   150→}
