   165→            return Err("requires arguments".to_string());
   166→        }
   167→        Ok(Value::Number(args[0].to_number().sqrt()))
   168→    }
   169→
   170→    #[test]
   171→    fn test_cache_creation() {
   172→        let cache = FunctionCache::new();
   173→        assert_eq!(cache.max_capacity, 8);
   174→        assert_eq!(cache.cache.len(), 0);
   175→    }
   176→
   177→    #[test]
   178→    fn test_cache_insert_and_get() {
   179→        let mut cache = FunctionCache::new();
   180→
   181→        cache.insert("abs".to_string(), dummy_abs);
   182→        assert!(cache.get("abs").is_some());
