   184→    }
   185→
   186→    #[test]
   187→    fn test_cache_hit_rate() {
   188→        let mut cache = FunctionCache::with_capacity(2);
   189→
   190→        cache.insert("abs".to_string(), dummy_abs);
   191→        cache.insert("sqrt".to_string(), dummy_sqrt);
   192→
   193→        // Hit
   194→        let _ = cache.get("abs");
   195→        let _ = cache.get("abs");
   196→
   197→        // Miss
