   203→        assert!((stats.hit_rate - 66.66).abs() < 1.0);
   204→    }
   205→
   206→    #[test]
   207→    fn test_cache_lru_eviction() {
   208→        let mut cache = FunctionCache::with_capacity(2);
   209→
   210→        cache.insert("abs".to_string(), dummy_abs);
   211→        cache.insert("sqrt".to_string(), dummy_sqrt);
   212→
   213→        // Both should be present
   214→        assert!(cache.get("abs").is_some());
   215→        assert!(cache.get("sqrt").is_some());
   216→
   217→        // Add third function, should evict "abs" (LRU)
   218→        fn dummy_pow(args: Vec<Value>) -> Result<Value, String> {
   219→            if args.len() < 2 {
   220→                return Err("requires 2 arguments".to_string());
