   238→
   239→        // Access "abs" to make it recently used
   240→        let _ = cache.get("abs");
   241→
   242→        // Add "pow", should evict "sqrt" (not "abs")
   243→        fn dummy_pow(args: Vec<Value>) -> Result<Value, String> {
   244→            if args.len() < 2 {
   245→                return Err("requires 2 arguments".to_string());
   246→            }
   247→            Ok(Value::Number(args[0].to_number().powf(args[1].to_number())))
